SELECT c.id,r.name AS theme,r.id_season AS season_number,r.round AS round_number,c.id_zsl_round,c.state,c.rules_hash,c.current_playlist_id,c.playlist_revision,c.published_revision,(c.finalized_at IS NOT NULL) AS finalized,(c.next_finalization_at<=clock_timestamp()) AS finalization_due FROM zc_private.level_submission_contest c JOIN public.zsl_round r ON r.id=c.id_zsl_round WHERE c.id_zsl_round=$1
